// Resumo da manhã da BMH no Telegram (8h): ontem e o mês até ontem, com os mesmos números do painel (anúncios gravados às
// 6h10, iGut às 3h20, cliques no WhatsApp do Analytics). Só números, sem dado de paciente.
const linhas = n => $(n).all().map(i => i.json).filter(r => r && r.chave);
const cfg = Object.fromEntries(linhas('Config').map(r => [r.chave, r.valor]));
const ads = linhas('Anúncios (tabela)'), site = linhas('Site · cliques (tabela)'), igut = linhas('iGut (tabela)'), guard = linhas('Guardião (tabela)');
const num = v => Number(v) || 0, entre = (d, a, b) => d >= a && d <= b;
const brl = v => 'R$ ' + Math.round(num(v)).toLocaleString('pt-BR'), int = v => Math.round(num(v)).toLocaleString('pt-BR');
const pct = (a, b) => b ? (a >= b ? '+' : '') + Math.round((a / b - 1) * 100) + '%' : '';
const hoje = $now.setZone('America/Sao_Paulo').startOf('day'), ontem = hoje.minus({ days: 1 }).setLocale('pt-BR');
const O = ontem.toISODate(), M0 = ontem.startOf('month').toISODate();
const ant = ontem.minus({ months: 1 }), A0 = ant.startOf('month').toISODate(), A1 = ant.set({ day: Math.min(ontem.day, ant.daysInMonth) }).toISODate();
const mesNome = d => d.setLocale('pt-BR').toFormat('LLLL');
// mesmo período do ano anterior (pedido do Jorge, 28/10/2026): a BMH tem sazonalidade, o mês anterior sozinho engana
const ano = ontem.minus({ years: 1 }), Y0 = ano.startOf('month').toISODate(), Y1 = ano.set({ day: Math.min(ontem.day, ano.daysInMonth) }).toISODate();
const soma = (rs, f) => rs.reduce((s, r) => s + num(r[f]), 0);
// anúncios
const adsO = ads.filter(r => r.dia === O), adsM = ads.filter(r => entre(r.dia, M0, O));
const gO = soma(adsO, 'gasto'), cO = soma(adsO, 'contatos') + soma(adsO, 'ligacoes'), gM = soma(adsM, 'gasto'), cM = soma(adsM, 'contatos') + soma(adsM, 'ligacoes');
// projeção igual à do guardião: gasto até ontem + orçamento diário de hoje × dias que faltam (com hoje)
const teto = num(cfg['teto_mes_' + M0.slice(0, 7)] || cfg.teto_mes), restantes = ontem.daysInMonth - ontem.day;
let B = null;
try {
  const tok = $('Google · renova o acesso').first().json.access_token;
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://googleads.googleapis.com/v25/customers/5066798424/googleAds:search', headers: { Authorization: 'Bearer ' + tok },
    body: { query: "SELECT campaign_budget.resource_name, campaign_budget.amount_micros FROM campaign WHERE campaign.status = 'ENABLED' AND campaign.experiment_type = 'BASE'" }, json: true, timeout: 60000 });
  const orc = {}; for (const x of r.results || []) orc[x.campaignBudget.resourceName] = Number(x.campaignBudget.amountMicros) / 1e6;
  B = Object.values(orc).reduce((s, v) => s + v, 0);
} catch (e) {}
// saldo da conta pré-paga (pedido do Jorge, 03/11/2026: "sempre avisar se estiver próximo de terminar"): crédito aprovado
// menos o já gasto (o Google atualiza com algumas horas de atraso); os dias saem da média real dos últimos 7 dias
let saldo = null;
try {
  const tok = $('Google · renova o acesso').first().json.access_token;
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://googleads.googleapis.com/v25/customers/5066798424/googleAds:search', headers: { Authorization: 'Bearer ' + tok },
    body: { query: "SELECT account_budget.status, account_budget.approved_spending_limit_micros, account_budget.adjusted_spending_limit_micros, account_budget.amount_served_micros, account_budget.approved_end_time_type, account_budget.approved_end_date_time FROM account_budget WHERE account_budget.status = 'APPROVED'" }, json: true, timeout: 60000 });
  const vigente = (r.results || []).map(x => x.accountBudget).filter(b => (b.approvedSpendingLimitMicros || b.adjustedSpendingLimitMicros) && (b.approvedEndTimeType === 'FOREVER' || String(b.approvedEndDateTime || '') > hoje.toFormat('yyyy-MM-dd HH:mm:ss')));
  if (vigente.length) saldo = vigente.reduce((s, b) => s + (Number(b.adjustedSpendingLimitMicros || b.approvedSpendingLimitMicros) - Number(b.amountServedMicros || 0)) / 1e6, 0);
} catch (e) {}
const S7 = hoje.minus({ days: 7 }).toISODate(), media7 = soma(ads.filter(r => entre(r.dia, S7, O)), 'gasto') / 7;
const diasSaldo = saldo !== null && media7 > 0 ? Math.floor(saldo / media7) : null;
// Meta pré-paga (mesmo pedido): o que acaba primeiro, o saldo pago ou o limite de gastos da conta, e a média dos últimos 7 dias
let meta = null;
try {
  const m = $('Meta · saldo da conta').first().json;
  const txt = String(m.funding_source_details?.display_string || '').match(/R\$\s*([\d.,]+)/), cap = num(m.spend_cap) / 100;
  const pago = txt ? Number(/,\d{2}$/.test(txt[1]) ? txt[1].replace(/\./g, '').replace(',', '.') : txt[1].replace(/,/g, '')) : null;
  const limite = cap > 0 ? cap - num(m.amount_spent) / 100 : null;
  const resta = [pago, limite].filter(v => v !== null && Number.isFinite(v));
  if (m.is_prepay_account && resta.length) {
    const dia = num(m.insights?.data?.[0]?.spend) / 7, v = Math.min(...resta);
    meta = { v, dia, pelo: limite !== null && limite <= v && (pago === null || limite < pago) ? 'limite' : 'saldo', dias: dia > 0 ? Math.floor(v / dia) : null };
  }
} catch (e) {}
const proj = B === null ? gM / ontem.day * ontem.daysInMonth : gM + B * (restantes || 0);
const cada = (g, c) => c >= 0.5 ? ` (${brl(g / c)} cada)` : '';
// WhatsApp pelo site
const wO = site.filter(r => r.dia === O && r.tipo === 'whatsapp'), PAGO = c => /Paid|Cross-network/.test(c || '');
const wTot = soma(wO, 'cliques'), wAds = soma(wO.filter(r => PAGO(r.canal)), 'cliques');
// iGut
const igO = igut.filter(r => r.dia === O), igM = igut.filter(r => entre(r.dia, M0, O)), igA = igut.filter(r => entre(r.dia, A0, A1)), igY = igut.filter(r => entre(r.dia, Y0, Y1));
const porUn = igO.map(r => r.unidade + ' ' + int(r.atendimentos)).join(' · ');
const sM = soma(igM, 'atendimentos'), vM = soma(igM, 'valor'), sA = soma(igA, 'atendimentos'), vA = soma(igA, 'valor'), sY = soma(igY, 'atendimentos'), vY = soma(igY, 'valor');
// guardião de hoje
const gHoje = guard.filter(r => r.data === hoje.toISODate());
const pendentes = gHoje.filter(r => r.acao !== 'avisar' && r.resultado === 'simulado' && r.plataforma !== 'meta').length;
// avisos de dado atrasado
const atraso = [];
const ultima = ads.map(r => r.atualizado_em || '').sort().pop() || '';
if (ultima.slice(0, 10) < hoje.toISODate()) atraso.push('⚠️ A gravação dos anúncios das 6h10 não rodou hoje: os números do Google Ads podem estar incompletos.');
if (!igO.length) atraso.push('⚠️ O iGut de ontem ainda não chegou (a busca é às 3h20).');
// Meta (21/10/2026): bloco lido da BMH_meta_anuncios_dia
// Copiado de scripts/n8n/bmh-meta-numeros.js e bmh-meta-guardiao-decide.js (BMH_Claude_VSL) pelo monta-numeros-meta.py: editar lá.
// Números do Meta Ads da BMH (21/10/2026): o que a "BMH · Meta · números do dia" grava na BMH_meta_anuncios_dia e o bloco do
// Meta no resumo das 8h, lido dessa tabela (lição da Nexo: painel, resumo e guardião leem a mesma fonte e nunca discordam).
// A verba da conta vem de verbaDaConta (bmh-meta-guardiao-decide.js), a mesma conta do guardião. Fonte: este arquivo; os
// montadores embutem o texto nos nós do n8n e o testa-numeros-meta.js roda com os dados de verdade pelo cofre.
//
// Tabela BMH_meta_anuncios_dia: uma linha por anúncio por dia (tipo "anuncio", chave dia|ad_id) e uma foto da conta por dia
// (tipo "conta", chave dia|conta). Só números e nomes de campanha e anúncio: nada de lead, conversa ou paciente.
const COLUNAS_META_DIA = {
  chave: 'string', dia: 'string', tipo: 'string', campanha_id: 'string', campanha: 'string', conjunto_id: 'string',
  conjunto: 'string', ad_id: 'string', anuncio: 'string', gasto: 'number', impressoes: 'number', alcance: 'number',
  cliques_link: 'number', conversas: 'number', verba_restante: 'number', orcamento_ligado: 'number', ritmo: 'number',
  dias_restantes: 'number', acaba_em: 'string', fonte_verba: 'string', atualizado_em: 'string',
};

// Q: hoje, agora (ISO); lidas: chave da leitura → resposta da Graph (anuncios, conta, campanhas, conjuntos, dias7).
function linhasDoDia(Q, lidas) {
  const CONV = 'onsite_conversion.messaging_conversation_started_7d';
  const num = v => Number(v) || 0, r2 = v => Math.round(num(v) * 100) / 100;
  const lista = r => (r && Array.isArray(r.data)) ? r.data : [];
  for (const [k, r] of Object.entries(lidas)) if (!r || r.error) throw new Error(`não consegui ler "${k}" na Meta: ` +
    String(r && r.error ? (r.error.message || JSON.stringify(r.error)) : 'sem resposta').replace(/(access_token|token)=[^&\s"']+/gi, '$1=[removido]').slice(0, 250));
  // mais de uma página num dia: não grava pela metade
  if (lidas.anuncios.paging && lidas.anuncios.paging.next) throw new Error('a Meta devolveu mais de 500 anúncios num dia: falta paginar');
  const vazio = { campanha_id: '', campanha: '', conjunto_id: '', conjunto: '', ad_id: '', anuncio: '', gasto: 0, impressoes: 0, alcance: 0,
    cliques_link: 0, conversas: 0, verba_restante: 0, orcamento_ligado: 0, ritmo: 0, dias_restantes: 0, acaba_em: '', fonte_verba: '' };
  const linhas = lista(lidas.anuncios).map(x => {
    const a = Object.fromEntries((x.actions || []).map(y => [y.action_type, num(y.value)]));
    return { ...vazio, chave: x.date_start + '|' + x.ad_id, dia: x.date_start, tipo: 'anuncio', campanha_id: String(x.campaign_id || ''),
      campanha: x.campaign_name || '', conjunto_id: String(x.adset_id || ''), conjunto: x.adset_name || '', ad_id: String(x.ad_id || ''),
      anuncio: x.ad_name || '', gasto: r2(x.spend), impressoes: num(x.impressions), alcance: num(x.reach),
      cliques_link: num(x.inline_link_clicks), conversas: a[CONV] || 0, atualizado_em: Q.agora };
  });
  // Trava (21/10/2026): a soma dos anúncios de cada dia tem de bater com o gasto da conta no dia (diferença até R$ 0,50 ou 2%).
  // Não bateu: a Meta devolveu dado incompleto, e nada é gravado (o fluxo termina em erro e passa pelo alerta de falha).
  const contaDia = Object.fromEntries(lista(lidas.contaDia).map(x => [x.date_start, num(x.spend)]));
  const somaDia = {};
  for (const l of linhas) somaDia[l.dia] = (somaDia[l.dia] || 0) + l.gasto;
  for (const dia of [...new Set([...Object.keys(contaDia), ...Object.keys(somaDia)])].sort()) {
    const a = r2(somaDia[dia] || 0), c = r2(contaDia[dia] || 0);
    if (Math.abs(a - c) > Math.max(0.5, c * 0.02))
      throw new Error(`o gasto por anúncio de ${dia} (R$ ${a.toFixed(2)}) não bate com o da conta (R$ ${c.toFixed(2)}): a Meta devolveu dado incompleto e nada foi gravado`);
  }
  const V = verbaDaConta({ ...lidas, hoje: Q.hoje });
  linhas.push({ ...vazio, chave: Q.hoje + '|conta', dia: Q.hoje, tipo: 'conta', verba_restante: V.verba === null ? 0 : r2(V.verba),
    orcamento_ligado: r2(V.B), ritmo: r2(V.ritmo), dias_restantes: V.dias === null ? 0 : Math.round(V.dias * 10) / 10,
    acaba_em: V.acaba || '', fonte_verba: V.quem || '', atualizado_em: Q.agora });
  return linhas;
}

// Junta as respostas de uma leitura feita um dia por vez (uma resposta por dia) numa só, no formato da Graph.
function juntaDias(respostas) {
  const erro = respostas.find(r => !r || r.error);
  if (erro) return erro || { error: { message: 'sem resposta' } };
  return { data: respostas.flatMap(r => r.data || []), paging: respostas.some(r => r.paging && r.paging.next) ? { next: true } : null };
}

// Bloco do Meta no resumo das 8h. rows: linhas da BMH_meta_anuncios_dia; D: O (ontem), M0 (1º do mês de ontem), hoje,
// diaOntem, diasMes. Devolve as linhas de ontem, as do mês e os avisos de dado atrasado.
function blocoMeta(rows, cfg, D) {
  const num = v => Number(v) || 0;
  const brl = v => 'R$ ' + Math.round(num(v)).toLocaleString('pt-BR'), int = v => Math.round(num(v)).toLocaleString('pt-BR');
  const dm = d => d.slice(8, 10) + '/' + d.slice(5, 7);
  const soma = (rs, f) => rs.reduce((s, r) => s + num(r[f]), 0);
  const cada = (g, c) => c >= 0.5 ? ` (${brl(g / c)} cada)` : '';
  const ads = rows.filter(r => r.tipo === 'anuncio');
  const aO = ads.filter(r => r.dia === D.O), aM = ads.filter(r => r.dia >= D.M0 && r.dia <= D.O);
  const gO = soma(aO, 'gasto'), cvO = soma(aO, 'conversas'), clO = soma(aO, 'cliques_link'), gM = soma(aM, 'gasto'), cvM = soma(aM, 'conversas');
  const conta = rows.filter(r => r.tipo === 'conta').sort((a, b) => (a.dia < b.dia ? -1 : 1)).pop();
  const deHoje = conta && conta.dia === D.hoje;
  const teto = num(cfg['meta_teto_mes_' + D.M0.slice(0, 7)] || cfg.meta_teto_mes);
  const noArAte = cfg.meta_no_ar_ate || '2026-10-31';
  const restantes = D.diasMes - D.diaOntem;
  const out = { ontem: [], mes: [], atraso: [] };
  out.ontem.push('📘 Meta Ads: ' + brl(gO) + ' · ' + (cvO >= 0.5 ? int(cvO) + (Math.round(cvO) === 1 ? ' conversa' : ' conversas') + cada(gO, cvO) : 'nenhuma conversa') +
    ' · ' + int(clO) + (Math.round(clO) === 1 ? ' clique' : ' cliques') + ' no link');
  const B = deHoje ? num(conta.orcamento_ligado) : null, proj = B === null ? null : gM + B * restantes;
  out.mes.push('• Meta: ' + brl(gM) + (teto ? ' de ' + brl(teto) : '') + (proj === null ? '' : ' · com ' + brl(B) + '/dia, fecha em ' + brl(proj)) +
    (teto && proj !== null && proj > teto * 1.02 ? ' ⚠️ acima do teto' : ''));
  out.mes.push('• Conversas do Meta: ' + int(cvM) + cada(gM, cvM));
  if (deHoje && num(conta.verba_restante) > 0) out.mes.push('• Verba da conta Meta: ' + brl(conta.verba_restante) +
    (num(conta.dias_restantes) ? ', dura ~' + num(conta.dias_restantes).toLocaleString('pt-BR', { maximumFractionDigits: 1 }) + ' dias' + (conta.acaba_em ? ' (até ' + dm(conta.acaba_em) + ')' : '') : '') +
    (conta.acaba_em && conta.acaba_em < noArAte && D.hoje <= noArAte ? ' ⚠️ antes de ' + dm(noArAte) : ''));
  if (!deHoje) out.atraso.push('⚠️ A gravação do Meta das 6h05 não rodou hoje: os números do Meta podem estar incompletos.');
  return out;
}
const META = blocoMeta(linhas('Meta (tabela)'), cfg, { O, M0, hoje: hoje.toISODate(), diaOntem: ontem.day, diasMes: ontem.daysInMonth });
const t = [];
t.push('🧪 (homologação) ☀️ BMH · resumo de ontem, ' + ontem.toFormat('cccc, dd/LL'));
t.push('');
t.push('📣 Google Ads: ' + brl(gO) + ' · ' + (cO >= 0.5 ? int(cO) + (Math.round(cO) === 1 ? ' contato' : ' contatos') + cada(gO, cO) : 'nenhum contato'));
t.push(...META.ontem);
t.push('💬 WhatsApp pelo site: ' + int(wTot) + (wTot === 1 ? ' clique' : ' cliques') + (wTot ? ` (${int(wAds)} de anúncio, ${int(wTot - wAds)} de busca e outros)` : ''));
if (igO.length) t.push('🏥 iGut: ' + int(soma(igO, 'atendimentos')) + ' sessões (' + porUn + ') · ' + brl(soma(igO, 'valor')) + ' produzidos');
t.push('');
t.push('📅 ' + mesNome(ontem).replace(/^./, c => c.toUpperCase()) + ' até ontem (' + ontem.day + ' de ' + ontem.daysInMonth + ' dias)');
const ritmo = B === null ? ' · no ritmo, fecha em ' : ' · com ' + brl(B) + '/dia, fecha em ';
t.push('• Anúncios: ' + brl(gM) + (teto ? ' de ' + brl(teto) : '') + ritmo + brl(proj) + (teto && proj > teto * 1.02 ? ' ⚠️ acima do teto' : ''));
t.push('• Contatos do Google Ads: ' + int(cM) + cada(gM, cM));
t.push(...META.mes);
if (saldo !== null) t.push('• Saldo da conta do Google Ads: ' + brl(saldo) + (diasSaldo === null ? '' : diasSaldo <= 0 ? ' ⚠️ acabando hoje: faça o pagamento já'
  : ' · dá uns ' + diasSaldo + (diasSaldo === 1 ? ' dia' : ' dias') + ' (' + brl(media7) + '/dia), até ~' + hoje.plus({ days: diasSaldo }).toFormat('dd/LL') + (diasSaldo <= 7 ? ' ⚠️ faça o pagamento até ' + hoje.plus({ days: Math.max(diasSaldo - 2, 0) }).toFormat('dd/LL') : '')));
if (meta) t.push('• Saldo da Meta: ' + brl(meta.v) + (meta.pelo === 'limite' ? ' (limite de gastos da conta)' : '') + (meta.dias === null ? '' : meta.dias <= 0 ? ' ⚠️ acabando hoje: ' + (meta.pelo === 'limite' ? 'aumente o limite de gastos já' : 'faça o pagamento já')
  : ' · dá uns ' + meta.dias + (meta.dias === 1 ? ' dia' : ' dias') + ' (' + brl(meta.dia) + '/dia), até ~' + hoje.plus({ days: meta.dias }).toFormat('dd/LL') + (meta.dias <= 7 ? ' ⚠️ ' + (meta.pelo === 'limite' ? 'aumente o limite de gastos' : 'faça o pagamento') + ' até ' + hoje.plus({ days: Math.max(meta.dias - 2, 0) }).toFormat('dd/LL') : '')));
if (igM.length) t.push('• iGut: ' + int(sM) + ' sessões · ' + brl(vM) + ' produzidos');
if (igA.length) t.push('• Mesmo período de ' + mesNome(ant) + ': ' + int(sA) + ' sessões (' + pct(sM, sA) + ') · ' + brl(vA) + ' (' + pct(vM, vA) + ')');
if (igY.length) t.push('• Mesmo período de ' + mesNome(ano) + ' de ' + ano.year + ': ' + int(sY) + ' sessões (' + pct(sM, sY) + ') · ' + brl(vY) + ' (' + pct(vM, vY) + ')');
t.push('');
t.push('🛡️ Guardião: ' + (pendentes ? pendentes + (pendentes === 1 ? ' proposta esperando' : ' propostas esperando') + ' o seu Aplicar ou Ignorar (mensagens acima).' : gHoje.length ? 'só avisos hoje (mensagem acima).' : 'nada a corrigir hoje.'));
atraso.push(...META.atraso);
if (atraso.length) { t.push(''); t.push(...atraso); }
t.push('');
t.push('Painel: https://automacao.cannlink.com.br/webhook/bmh-painel');
return [{ json: { texto: t.join('\n') } }];
